        value = local.storage_emulator_host
      }
      env {
        name  = "DATABASE_URL"
        value = local.database_url
      }
      env {
        name  = "PUBSUB_TOPIC"
        value = google_pubsub_topic.events.name
      }
      env {
        name  = "FIRESTORE_DATABASE"
        value = google_firestore_database.projections.name
      }
      env {
        name  = "DATASTORE_NAMESPACE"
        value = "${var.prefix}-cache"
      }
      env {
        name  = "AUTH_ISSUER"
        value = local.auth_issuer
      }
      env {
        name  = "AUTH_AUDIENCES"
        value = local.auth_audiences
      }
      env {
        name  = "AUTH_JWKS_URL"
        value = local.auth_jwks_url
      }
      env {
        name  = "RUST_LOG"
        value = "info"
      }

      startup_probe {
        http_get {
          path = "/health/ready"
          port = 8080
        }
        initial_delay_seconds = 2
        period_seconds        = 5
        timeout_seconds       = 3
        failure_threshold     = 6
