      liveness_probe {
        http_get {
          path = "/health/ready"
          port = 8080
        }
        period_seconds    = 10
        timeout_seconds   = 3
        failure_threshold = 3
      }
    }
  }

  labels = merge(local.common_labels, {
    component = "api"
  })
}

